def transform(grid):
    """Transform grid by applying pattern rules to simple boxes"""
    result = [row[:] for row in grid]

    from collections import defaultdict
    color_to_cells = defaultdict(list)
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                color_to_cells[grid[r][c]].append((r, c))

    for cval, cells in color_to_cells.items():
        rs = [r for r, c in cells]
        cs = [c for r, c in cells]
        bbox = (min(rs), min(cs), max(rs), max(cs))
        h, w = max(rs) - min(rs) + 1, max(cs) - min(cs) + 1

        if is_simple_box(grid, cval, bbox):
            if h * w <= 25:  # 5x5 or smaller -> REMOVE
                result = remove_box(result, cval, bbox)
            elif h == 7 and w == 8:
                result = apply_7x8_pattern(result, cval, bbox)
        # Complex boxes unchanged
    return result


def is_simple_box(grid, cval, bbox):
    min_r, min_c, max_r, max_c = bbox
    h, w = max_r - min_r + 1, max_c - min_c + 1
    for r in range(h):
        for c in range(w):
            if grid[min_r+r][min_c+c] == cval:
                if not (r == 0 or r == h-1 or c == 0 or c == w-1):
                    return False
    return True


def remove_box(grid, cval, bbox):
    min_r, min_c, max_r, max_c = bbox
    h, w = max_r - min_r + 1, max_c - min_c + 1
    result = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            result[min_r+r][min_c+c] = 0
    return result


# The exact pattern from observation:
# Row 1: fill col 6
# Row 2: fill cols 2,3
# Row 3: fill cols 1,2,4,5
# Row 4: fill cols 3,4,6
# Row 5: fill col 5
def apply_7x8_pattern(grid, cval, bbox):
    min_r, min_c, max_r, max_c = bbox
    result = [row[:] for row in grid]

    pattern = [
        [0, 0, 0, 0, 0, 0, 0, 0],  # border
        [0, 0, 0, 0, 0, 0, 1, 0],  # fill col 6
        [0, 0, 1, 1, 0, 0, 0, 0],  # fill cols 2,3
        [0, 1, 1, 0, 1, 1, 0, 0],  # fill cols 1,2,4,5  
        [0, 0, 0, 1, 1, 0, 1, 0],  # fill cols 3,4,6
        [0, 0, 0, 0, 0, 1, 0, 0],  # fill col 5
        [0, 0, 0, 0, 0, 0, 0, 0],  # border
    ]

    for r in range(7):
        for c in range(8):
            if pattern[r][c] == 1 and result[min_r+r][min_c+c] == 0:
                result[min_r+r][min_c+c] = cval
    return result


